arguments.new_str:
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);

var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "tickets.csv");
builder.Services.AddSingleton(new TicketClassifierService(dataPath));

var app = builder.Build();

app.MapPost("/api/tickets/classify", (TicketRequest request, TicketClassifierService classifier) =>
{
    if (string.IsNullOrWhiteSpace(request.Subject) && string.IsNullOrWhiteSpace(request.Description))
        return Results.BadRequest("Subject or Description is required.");

    if (request.Priority is < 1 or > 3)
        return Results.BadRequest("Priority must be between 1 and 3.");

    var (prediction, _) = classifier.Predict(request);
    return Results.Ok(prediction);
});

app.MapGet("/api/tickets/metrics", (TicketClassifierService classifier) =>
{
    return Results.Ok(classifier.GetEvaluationMetrics());
});

app.Run();

